INSERT INTO machine_project_requests(id,request_frame_id,requester_machine_id,requester_session_id,requester_connection_id,project_id,holder_machine_id,phase,deadline_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,CAST(? AS INTEGER),CAST(? AS INTEGER),CAST(? AS INTEGER)) ON CONFLICT(id) DO UPDATE SET holder_machine_id=excluded.holder_machine_id,phase=excluded.phase,updated_at=excluded.updated_at;
